package palindrome

import (
	"errors"
	"fmt"
)

type Product struct {
	Product        int
	Factorizations [][2]int
}

func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	var minP, maxP Product
	minFound, maxFound := false, false

	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			product := i * j
			if !isPalindrome(product) {
				continue
			}
			if !minFound || product < minP.Product {
				minP = Product{product, [][2]int{{i, j}}}
				minFound = true
			} else if product == minP.Product {
				minP.Factorizations = append(minP.Factorizations, [2]int{i, j})
			}
			if !maxFound || product > maxP.Product {
				maxP = Product{product, [][2]int{{i, j}}}
				maxFound = true
			} else if product == maxP.Product {
				maxP.Factorizations = append(maxP.Factorizations, [2]int{i, j})
			}
		}
	}

	if !minFound {
		return Product{}, Product{}, errors.New("no palindromes found in the given range")
	}
	return minP, maxP, nil
}

func isPalindrome(n int) bool {
	// Handle negatives: treat as not a palindrome (most say no)
	if n < 0 {
		return false
	}
	s := strconv.Itoa(n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}
```

