package palindrome

import (
	"errors"
	"fmt"
	"strconv"
)

// Product contains a palindromic product and the factor pairs that produce it.
type Product struct {
	Product        int
	Factorizations [][2]int
}

// Products finds the smallest and largest palindromic numbers that can be
// written as a product of two numbers in the range [fmin, fmax] (inclusive).
// For each, it also records every factor pair within the range.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	var minP, maxP Product

	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			product := i * j
			if !isPalindrome(product) {
				continue
			}
