package palindrome

import (
	"errors"
	"fmt"
	"strconv"
)

// Product holds a palindromic product together with the factor pairs within
// the given range that produce it.
type Product struct {
	Product        int
	Factorizations [][2]int
}

// Products finds the smallest and largest palindromic numbers that are
// products of two numbers in the range [fmin, fmax] (both inclusive),
// along with all factor pairs within the range for each.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	var minP, maxP Product

	// Iterate the upper triangle (j >= i) so each unordered factor pair is
	// visited exactly once, with the smaller factor first.
	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			product := i * j
			if !isPalindrome(product) {
				continue
			}
			if minP.Factorizations == nil || product < minP.Product {
				minP = Product{product, [][2]int{{i, j}}}
			} else if product == minP.Product {
				minP.Factorizations = append(minP.Factorizations, [2]int{i, j})
			}
			if maxP.Factorizations == nil || product > maxP.Product {
				maxP = Product{product, [][2]int{{i, j}}}
			} else if product == maxP.Product {
				maxP.Factorizations = append(maxP.Factorizations, [2]int{i, j})
			}
		}
	}

	if minP.Factorizations == nil {
		return Product{}, Product{}, fmt.Errorf("no palindromes found for factors in the range [%d, %d]", fmin, fmax)
	}

	return minP, maxP, nil
}

// isPalindrome reports whether n reads the same forwards and backwards.
// Negative numbers are not considered palindromes.
func isPalindrome(n int) bool {
	if n < 0 {
		return false
	}
	s := strconv.Itoa(n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}
